#!/usr/bin/env bash
# Uruchamiaj wyłącznie w kopii runtime, po przygotuj-runtime.sh gpt-2fa-ustawienia.
set -euo pipefail
cd "$(dirname "$0")/../.."
[ "$(pwd)" = /home/mateusz/flota/gpt-2fa-ustawienia-run ] || { echo 'Odmowa: wymagany własny runtime.'; exit 2; }
export PATH=/opt/kuking-php-8.4-avif/bin:$PATH
export DB_CONNECTION=pgsql DB_HOST=127.0.0.1 DB_PORT=55439 DB_DATABASE=kuking_flota_gpt-2fa-ustawienia DB_USERNAME=kuking DB_PASSWORD=kuking
mkdir -p output/playwright/2fa
bash scripts/kontrola-ujemna.sh --nazwa '876 instrukcja konta Google' --plik resources/views/pages/settings/two_factor/_password-help.blade.php --zamien 'Jeśli logujesz się przez Google' --na 'Jeśli logujesz się przez dostawcę' --oczekuj 'Failed asserting that 0 is identical to 2' --json output/playwright/2fa/ujemna-876.json -- bash -c 'php artisan view:clear >/dev/null; if grep -qF "Jeśli logujesz się przez dostawcę" resources/views/pages/settings/two_factor/_password-help.blade.php; then ! grep -qF "Jeśli logujesz się przez Google" resources/views/pages/settings/two_factor/_password-help.blade.php || exit 2; echo MUTACJA_876_POTWIERDZONA; fi; php artisan test --filter Ustawienia2faHasloGoogleTest'
bash scripts/kontrola-ujemna.sh --nazwa '811 sekcja z błędem' --plik resources/views/pages/settings/two_factor/index.blade.php --zamien "@if(\$errors->getBag('regenerate')->any()) open @endif" --na '' --oczekuj 'Błąd hasła musi otworzyć właściwy details' --json output/playwright/2fa/ujemna-811-open.json -- bash -c 'php artisan view:clear >/dev/null; if ! grep -qF "regenerate'"'"')->any()) open" resources/views/pages/settings/two_factor/index.blade.php; then echo MUTACJA_811_POTWIERDZONA; fi; php artisan test --filter Ustawienia2faBledyTest'
bash scripts/kontrola-ujemna.sh --nazwa '811 unikalne identyfikatory' --plik resources/views/pages/settings/two_factor/index.blade.php --zamien 'f-password-disable' --na 'f-password-regenerate' --oczekuj 'Powielony identyfikator pola lub opisu' --json output/playwright/2fa/ujemna-811-id.json -- bash -c 'php artisan view:clear >/dev/null; if ! grep -qF f-password-disable resources/views/pages/settings/two_factor/index.blade.php; then grep -qF f-password-regenerate resources/views/pages/settings/two_factor/index.blade.php || exit 2; echo MUTACJA_811_ID_POTWIERDZONA; fi; php artisan test --filter Ustawienia2faBledyTest'
bash scripts/kontrola-ujemna.sh --nazwa '875 niejednoznaczne znaki' --plik app/Domain/Security/TwoFactorAuthenticator.php --zamien ABCDEFGHJKLMNPQRSTUVWXYZ23456789 --na 0O1I --oczekuj 'Kod ma mieć dwie grupy po pięć jednoznacznych znaków' --json output/playwright/2fa/ujemna-875.json -- bash -c 'php artisan view:clear >/dev/null; if grep -qF "0O1I" app/Domain/Security/TwoFactorAuthenticator.php; then ! grep -qF ABCDEFGHJKLMNPQRSTUVWXYZ23456789 app/Domain/Security/TwoFactorAuthenticator.php || exit 2; echo MUTACJA_875_POTWIERDZONA; fi; php artisan test --filter KodyZapasoweCzytelnyAlfabetTest'
bash scripts/kontrola-ujemna.sh --nazwa '877 zakaz przechowywania odpowiedzi' --plik app/Http/Controllers/Settings/TwoFactorSettingsController.php --zamien 'no-store, private' --na 'no-cache, private' --oczekuj 'Odpowiedź zawierająca kody musi mieć no-store' --json output/playwright/2fa/ujemna-877.json -- bash -c 'php artisan view:clear >/dev/null; if grep -qF "no-cache, private" app/Http/Controllers/Settings/TwoFactorSettingsController.php; then ! grep -qF "no-store, private" app/Http/Controllers/Settings/TwoFactorSettingsController.php || exit 2; echo MUTACJA_877_POTWIERDZONA; fi; php artisan test --filter KodyZapasowePamiecPrzegladarkiTest'